-- ============================================================================
-- Rede de Apoio — Migration: ampliação da rede de Curitiba com dados do IPPUC
-- Depende de: base_curitiba, canais_categorias_conteudo. Idempotente.
--
-- Fonte: camadas públicas do GeoCuritiba (IPPUC / Prefeitura de Curitiba),
-- consultadas em 25/09/2026, com coordenadas oficiais:
--   34  Centro de Referência de Assistência Social (CRAS)        -> 39
--   38  Centro de Referência Especializado de Assist. Social     -> 10
--   130 Unidade de Pronto Atendimento (UPA 24h)                   -> 9
--   143 Polícia Civil (13 distritos + Central de Flagrantes)      -> 14
--   105 Defensoria Pública (postos úteis às usuárias)             -> 9
--   108 Centro de Referência de Atendimento à Mulher (CRAM CIC)   -> 1
-- Total: 82 instituições. Todas as coordenadas foram conferidas
-- convertendo coord_e/coord_n (SIRGAS 2000 / UTM 22S) de forma independente.
--
-- verified_at = data da conferência com a fonte oficial (não significa que a
-- equipe ligou para o local). A confirmação por telefone segue na rotina.
-- ============================================================================

-- 1. Categorias: "delegacia_comum" passa a representar a Polícia Civil em geral
--    (distritos e delegacias especializadas).
UPDATE public.institution_categories
SET label = 'Delegacia de Polícia Civil',
    description = 'Distritos policiais e delegacias especializadas'
WHERE id = 'delegacia_comum';

