-- 4. Busca: limite máximo de resultados passa de 50 para 200, para o mapa
--    mostrar todos os locais do raio (a base agora tem ~90 instituições).
CREATE OR REPLACE FUNCTION public.search_institutions(
  q                 TEXT    DEFAULT NULL,
  lat               FLOAT   DEFAULT NULL,
  lng               FLOAT   DEFAULT NULL,
  filter_city       TEXT    DEFAULT NULL,
  filter_categories TEXT[]  DEFAULT NULL,
  radius_meters     INT     DEFAULT NULL,
  max_results       INT     DEFAULT 30
)
RETURNS TABLE (
  id                 UUID,
  external_key       VARCHAR(100),
  name               VARCHAR(200),
  category           VARCHAR(50),
  subcategory        VARCHAR(100),
  address            TEXT,
  district           VARCHAR(100),
  city               VARCHAR(100),
  state              CHAR(2),
  zip_code           VARCHAR(10),
  phone              VARCHAR(20),
  phone2             VARCHAR(20),
  email              VARCHAR(150),
  website            VARCHAR(250),
  opening_hours      JSONB,
  latitude           FLOAT,
  longitude          FLOAT,
  services           TEXT[],
  target_audience    TEXT,
  verified_at        TIMESTAMPTZ,
  source_name        TEXT,
  source_url         TEXT,
  location_precision VARCHAR(20),
  distance_km        FLOAT
)
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = ''
AS $$
  WITH params AS (
    SELECT
      CASE WHEN lat IS NOT NULL AND lng IS NOT NULL
           THEN extensions.ST_SetSRID(extensions.ST_MakePoint(lng, lat), 4326)::extensions.geography
      END AS origin,
      array_remove(
        regexp_split_to_array(public.f_normalize(trim(coalesce(q, ''))), '\s+'),
        ''
      ) AS terms
  )
  SELECT
    i.id,
    i.external_key,
    i.name,
    i.category,
    i.subcategory,
    i.address,
    i.district,
    i.city,
    i.state,
    i.zip_code,
    i.phone,
    i.phone2,
    i.email,
    i.website,
    i.opening_hours,
    extensions.ST_Y(i.location::extensions.geometry)::FLOAT AS latitude,
    extensions.ST_X(i.location::extensions.geometry)::FLOAT AS longitude,
    i.services,
    i.target_audience,
    i.verified_at,
    i.source_name,
    i.source_url,
    i.location_precision,
    CASE WHEN p.origin IS NOT NULL
         THEN round((extensions.ST_Distance(i.location, p.origin) / 1000.0)::numeric, 2)::FLOAT
    END AS distance_km
  FROM public.institutions i
  CROSS JOIN params p
  WHERE i.is_active = true
    AND i.category <> 'casa_abrigo'
    AND (filter_city IS NULL OR public.f_normalize(i.city) = public.f_normalize(filter_city))
    AND (filter_categories IS NULL OR cardinality(filter_categories) = 0
         OR i.category = ANY (filter_categories))
    AND NOT EXISTS (
      SELECT 1 FROM unnest(p.terms) AS t(term)
      WHERE position(t.term IN i.search_text) = 0
    )
    AND (
      p.origin IS NULL OR radius_meters IS NULL OR radius_meters <= 0
      OR extensions.ST_DWithin(i.location, p.origin, radius_meters)
    )
  ORDER BY
    CASE WHEN p.origin IS NOT NULL THEN extensions.ST_Distance(i.location, p.origin) END ASC NULLS LAST,
    CASE WHEN cardinality(p.terms) > 0
         THEN extensions.similarity(i.search_text, array_to_string(p.terms, ' ')) END DESC NULLS LAST,
    i.name ASC
  LIMIT LEAST(GREATEST(coalesce(max_results, 30), 1), 200);
$$;

-- 5. Fila de revisão ----------------------------------------------------------
-- Pendências resolvidas por esta importação.
UPDATE public.institution_review_queue
SET status = 'aprovado', reviewed_by = 'importação IPPUC/GeoCuritiba', reviewed_at = now(),
    notes = coalesce(notes, '') || ' | Resolvido com dados do IPPUC.'
WHERE status = 'pendente'
  AND external_key IN ('cwb-hospital-trabalhador', 'cwb-hc-ufpr', 'cwb-nucria', 'cwb-nuciber', 'cwb-cras-creas');

-- Nova pendência: telefones divergentes da Delegacia da Mulher.
INSERT INTO public.institution_review_queue (institution_id, external_key, kind, source_name, source_url, notes)
SELECT i.id, i.external_key, 'reverificacao', 'IPPUC — GeoCuritiba', 'https://geocuritiba.ippuc.org.br/server/rest/services/Publico_GeoCuritiba_Equipamentos_Urbanos/MapServer/143',
       'IPPUC informa (41) 3219-8600; a Prefeitura informa (41) 3221-2742 / 3221-2745. Confirmar por telefone.'
FROM public.institutions i
WHERE i.external_key = 'cwb-delegacia-mulher'
  AND NOT EXISTS (
    SELECT 1 FROM public.institution_review_queue r
    WHERE r.external_key = 'cwb-delegacia-mulher' AND r.status = 'pendente'
  );
